<?php require 'config/auth.php';require_login();require 'config/database.php';$user_id=$_SESSION['user_id'];if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$stmt=$conn->prepare("DELETE FROM items WHERE id=? AND user_id=?");$stmt->bind_param("ii",$id,$user_id);$stmt->execute();header('Location: my-posts.php');exit;}$stmt=$conn->prepare("SELECT * FROM items WHERE user_id=? ORDER BY created_at DESC");$stmt->bind_param("i",$user_id);$stmt->execute();$res=$stmt->get_result();$pageTitle='My Posts';include 'header.php';?><h2>My Posts</h2><table><tr><th>Title</th><th>Type</th><th>Status</th><th>Action</th></tr><?php while($row=$res->fetch_assoc()):?><tr><td><?=htmlspecialchars($row['title'])?></td><td><?=htmlspecialchars($row['item_type'])?></td><td><?=htmlspecialchars($row['status'])?></td><td><a class="btn" href="item-details.php?id=<?=(int)$row['id']?>">View</a> <a class="btn danger" onclick="return confirmDelete()" href="?delete=<?=(int)$row['id']?>">Delete</a></td></tr><?php endwhile;?></table><?php include 'footer.php'; ?>